import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void l2norm_kernel(const __half* __restrict__ input,
                              __half* __restrict__ output,
                              const int batch,
                              const int dim) {
    // each block works on one batch element
    const int b = blockIdx.x;
    if (b >= batch) return;

    const __half* in_ptr = input + b * dim;
    __half* out_ptr = output + b * dim;

    // each thread accumulates partial sum of squares
    float sum = 0.0f;
    for (int idx = threadIdx.x; idx < dim; idx += BLOCK_SIZE) {
        __half v = __ldg(in_ptr + idx);
        float f = __half2float(v);
        sum += f * f;
    }

    // reduction within block (warp shuffle based)
    #pragma unroll
    for (int offset = BLOCK_SIZE / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // broadcast norm to all threads
    float norm = sqrtf(sum);
    norm = norm > 0.0f ? norm : 1.0f; // avoid division by zero
    float inv_norm = __fdividef(1.0f, norm);

    // second pass: write normalized values
    for (int idx = threadIdx.x; idx < dim; idx += BLOCK_SIZE) {
        __half v = __ldg(in_ptr + idx);
        float f = __half2float(v);
        float fn = f * inv_norm;
        out_ptr[idx] = __float2half(fn);
    }
}

// wrapper
at::Tensor l2norm_cuda(at::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::kHalf, "input must be fp16");
    TORCH_CHECK(input.dim() == 2, "input must be 2‑D (batch, dim)");

    const int batch = input.size(0);
    const int dim   = input.size(1);

    auto output = at::empty_like(input);

    const int threads = 256;
    const dim3 blocks(batch);
    const dim3 threads_per_block(threads);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input.scalar_type(), "l2norm_kernel", ([&] {
            l2norm_kernel<threads><<<blocks, threads_per_block, 0,
                at::cuda::getCurrentCUDAStream()>>>(
                reinterpret_cast<const __half*>(input.data_ptr()),
                reinterpret_cast<__half*>(output.data_ptr()),
                batch,
                dim);
        })
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel failed: ") + cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2norm_cuda", &l2norm_cuda, "L2‑norm across dim=1 (fp16)");
}
'''

# compile the extension
l2norm_ext = load_inline(name='l2norm_ext',
                         cpp_sources='',
                         cuda_sources=src,
                         functions=['l2norm_cuda'],
                         verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement of the reference Model using a custom CUDA kernel.
    """
